const num=(key,label,group='Assumptions',value='',max, min=0)=>({key,label,group,type:'number',value,max,min});
const select=(key,label,options,group='Context',value='')=>({key,label,group,type:'select',options,value});
const rating=(key,label,group)=>num(key,label+' (0–100; blank = unknown)',group,'',100);
