export const emptyValues=tool=>Object.fromEntries(tool.fields.map(f=>[f.key,f.value??'']));
export function validateValues(tool,input){const out=emptyValues(tool);for(const field of tool.fields){const v=input[field.key];if(v===undefined)continue;if(v===''||v===null){out[field.key]='';continue}if(field.type==='number'){if(typeof v!=='number'&&typeof v!=='string'||!Number.isFinite(Number(v))||Number(v)<field.min||field.max!==undefined&&Number(v)>field.max)throw Error('Invalid '+field.label);out[field.key]=Number(v)}else{if(typeof v!=='string'||v.length>20000||field.type==='select'&&!field.options.includes(v)||field.type==='date'&&(!/^\d{4}-\d{2}-\d{2}$/.test(v)||Number.isNaN(Date.parse(v))||new Date(v+'T00:00:00Z').toISOString().slice(0,10)!==v))throw Error('Invalid '+field.label);out[field.key]=v}}return out;}
export function validateProcesses(input){if(!Array.isArray(input)||input.length>100)throw Error('Expected at most 100 saved processes.');const tool=tools.find(t=>t.id==='opportunities');const records=input.map(p=>{if(!p||typeof p.id!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(p.id)||!p.values||typeof p.values!=='object'||Array.isArray(p.values))throw Error('Invalid saved process.');const values=validateValues(tool,p.values);if(!values.process.trim())throw Error('Saved processes need a name.');return {id:p.id,values}});if(new Set(records.map(p=>p.id)).size!==records.length)throw Error('Duplicate process IDs.');return records;}
